                    balance += 1
                else:
                    balance -= 1

                current_len = end - start + 1
                if current_len % 2 == 1:
                    median_idx = current_len // 2
                    if balance >= 1 and balance <= current_len:
                        if (balance - 1) % 2 == 0:
                            ans += 1
                else:
                    median_idx_left = current_len // 2 - 1
                    if balance >= 0 and balance <= current_len:
                        if (balance - 0) % 2 == 0:
                            ans += 1
        return ans

    def count_pairs_efficient(target_median):
