m_index = 0

while p_index < len(password) and m_index < len(message):
    found_char = False
    for i in range(m_index, len(message)):
        if message[i] == password[p_index]:
            m_index = i + 1
            p_index += 1
            found_char = True
            break
    if not found_char:
        break

if p_index == len(password):
    print("PASS")
else:
    print("FAIL")
