def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    counts = {}
    for x in a:
        counts[x] = counts.get(x, 0) + 1

    for count in counts.values():
        if count > k:
            print("NO")
            return

    print("YES")

    indexed_a = sorted([(a[i], i) for i in range(n)])

    colors = [0] * n

    for i in range(n):
        colors[indexed_a[i][1]] = (i % k) + 1

    print(*colors)

solve()
