def num_to_words(n):
    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    if 1 <= n <= 19:
        return units[n]
    elif 20 <= n <= 99:
        ten_digit = n // 10
        unit_digit = n % 10
        if unit_digit == 0:
            return tens[ten_digit]
        else:
            return tens[ten_digit] + units[unit_digit]
    elif 100 <= n <= 999:
        hundred_digit = n // 100
        remaining = n % 100
        if remaining == 0:
            return units[hundred_digit] + "hundred"
        else:
            return units[hundred_digit] + "hundred" + num_to_words(remaining)
    return ""

