import sys

def solve():
    n = int(sys.stdin.readline())
    c = list(map(int, sys.stdin.readline().split()))

    c.sort()

    if sum(c) < n * (n + 1) // 2:
        print("impossible")
        return

    def check(f):
        required_helium = [i * f for i in range(1, n + 1)]
        required_helium.sort()

        for i in range(n):
            if c[i] < required_helium[i]:
                return False
        return True

    low = 0.0
    high = 1.0
    for _ in range(100):
        mid = (low + high) / 2
        if check(mid):
            low = mid
        else:
            high = mid

    print(f"{low:.10f}")

if __name__ == "__main__":
    solve()
