import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    edges = []
    for _ in range(m):
        x, y, w = map(int, sys.stdin.readline().split())
        edges.append((w, x - 1, y - 1))

    min_a_idx = a.index(min(a))
    for i in range(n):
        if i != min_a_idx:
            edges.append((a[min_a_idx] + a[i], min_a_idx, i))

    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True
        return False

    min_cost = 0
    num_edges = 0
    for cost, u, v in edges:
        if union(u, v):
            min_cost += cost
            num_edges += 1
            if num_edges == n - 1:
                break

    print(min_cost)

if __name__ == "__main__":
    solve()
