    m = float(m)
    u = float(u)
    d = int(d)

    drinks = []
    for _ in range(d):
        line = input().split()
        name = line[0]
        strength = int(line[1])
        size_str = line[2]
        cost = float(line[3])

        if size_str == '1/1':
            size = 1.0
        elif size_str == '1/2':
            size = 0.5
        elif size_str == '1/3':
            size = 1.0/3.0
        else:
            continue

        alcohol_units_per_drink = (strength / 100.0) * size
        drinks.append((name, strength, size, cost, alcohol_units_per_drink))

    def find_solution(current_money, current_units, current_selection):
        if abs(current_money - m) < 1e-9 and abs(current_units - u) < 1e-9:
            return current_selection

        if current_money > m or current_units > u:
            return None

        for i in range(len(drinks)):
            name, strength, size, cost, alcohol_units_per_drink = drinks[i]

            # Try adding one more of this drink
            new_money = current_money + cost
            new_units = current_units + alcohol_units_per_drink
            new_selection = current_selection.copy()
            new_selection[i] = new_selection.get(i, 0) + 1

            result = find_solution(new_money, new_units, new_selection)
            if result:
                return result
        return None

    initial_selection = {}
    solution_indices = find_solution(0.0, 0.0, initial_selection)

    if solution_indices:
        output_lines = []
        for i, count in solution_indices.items():
            output_lines.append(f"{drinks[i][0]} {count}")
        print("\n".join(output_lines))
    else:
        print("IMPOSSIBLE")

solve()
