def solve():
    n = int(input())
    if n % 2 == 0:
        print(n // 2, n // 2)
    else:
        best_a = 1
        best_b = n - 1
        min_lcm = n - 1

        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                a = n // i
                b = n - a
                if a > 0 and b > 0:
                    current_lcm = (a * b) // gcd(a, b)
                    if current_lcm < min_lcm:
                        min_lcm = current_lcm
                        best_a = a
                        best_b = b
                break
        print(best_a, best_b)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

