def solve():
    n = int(input())
    s = input()
    m = int(input())

    t = ""
    for i in range(m):
        if i % 2 == 0:
            t += 'a'
        else:
            t += 'b'

    dp = [(0, 0)] * (n + 1)  # (max_occurrences, min_replacements)

    for i in range(1, n + 1):
        # Option 1: Don't end an occurrence at position i
        dp[i] = dp[i-1]

        # Option 2: Try to end an occurrence at position i
        if i >= m:
            start_index = i - m
            can_match = True
            replacements_needed = 0
            for j in range(m):
                if s[start_index + j] != '?' and s[start_index + j] != t[j]:
                    can_match = False
                    break
                if s[start_index + j] == '?':
                    replacements_needed += 1

            if can_match:
                prev_occurrences, prev_replacements = dp[start_index]
                current_occurrences = prev_occurrences + 1
                current_replacements = prev_replacements + replacements_needed

                if current_occurrences > dp[i][0]:
                    dp[i] = (current_occurrences, current_replacements)
                elif current_occurrences == dp[i][0] and current_replacements < dp[i][1]:
                    dp[i] = (current_occurrences, current_replacements)

    print(dp[n][1])

solve()
