def solve():
    n, s_str = input().split()
    n = int(n)
    s = int(s_str)

    participants = []
    for _ in range(n):
        name, bet_str = input().split()
        participants.append((name, int(bet_str)))

    winning_participants = set()

    for i in range(1 << n):
        current_sum = 0
        current_group_indices = []
        for j in range(n):
            if (i >> j) & 1:
                current_sum += participants[j][1]
                current_group_indices.append(j)

        if current_sum == s:
            for index in current_group_indices:
                winning_participants.add(participants[index][0])

    sorted_winners = sorted(list(winning_participants))
    print(len(sorted_winners))
    for winner in sorted_winners:
        print(winner)

solve()
