def solve():
    n = int(input())
    a = list(map(int, input().split()))
    mod = 10**9 + 7

    dp = [0] * (n + 1)
    dp[0] = 1

    for x in a:
        divisors = []
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                divisors.append(i)
                if i * i != x:
                    divisors.append(x // i)
        divisors.sort(reverse=True)

        for d in divisors:
            if d <= n:
                dp[d] = (dp[d] + dp[d - 1]) % mod

    ans = (sum(dp) - dp[0]) % mod
    print(ans)

if __name__ == "__main__":
    solve()
```

