def solve():
    available_weights_str = input()
    m = int(input())
    available_weights = [i + 1 for i, char in enumerate(available_weights_str) if char == '1']

    if not available_weights:
        print("NO")
        return

    memo = {}

    def find_sequence(k, left_sum, right_sum, last_weight, is_left_pan):
        if k == m:
            return []

        state = (k, left_sum, right_sum, last_weight, is_left_pan)
        if state in memo:
            return memo[state]

        for weight in available_weights:
            if weight == last_weight:
                continue

            if is_left_pan:
                if left_sum + weight > right_sum:
                    result = find_sequence(k + 1, left_sum + weight, right_sum, weight, not is_left_pan)
                    if result is not None:
                        memo[state] = [weight] + result
                        return memo[state]
            else: # right pan
                if right_sum + weight > left_sum:
                    result = find_sequence(k + 1, left_sum, right_sum + weight, weight, not is_left_pan)
                    if result is not None:
                        memo[state] = [weight] + result
                        return memo[state]

        memo[state] = None
        return None

    initial_result = find_sequence(0, 0, 0, -1, True)

    if initial_result is not None:
        print("YES")
        print(*initial_result)
    else:
        print("NO")

