import re

def solve():
    n = int(input())
    users = input().split()
    m = int(input())
    messages = []
    for _ in range(m):
        messages.append(input())

    def is_mentioned(text, username):
        pattern = r"(?<![a-zA-Z0-9])" + re.escape(username) + r"(?![a-zA-Z0-9])"
        return re.search(pattern, text) is not None

    def find_possible_senders(message_index, current_assignment):
        sender, text = messages[message_index].split(':', 1)
        if sender != '?':
            return [sender]

        possible = []
        prev_sender = None
        if message_index > 0:
            prev_sender = current_assignment[message_index - 1]

        for user in users:
            if user == prev_sender:
                continue
            if is_mentioned(text, user):
                continue
            possible.append(user)
        return possible

    assignment = [None] * m
    possible_assignments = [[] for _ in range(m)]

    for i in range(m):
        sender, text = messages[i].split(':', 1)
        if sender != '?':
            assignment[i] = sender
            possible_assignments[i] = [sender]
        else:
            possible_assignments[i] = find_possible_senders(i, assignment)
            if not possible_assignments[i]:
                return "Impossible"

    def backtrack(index):
        if index == m:
            return True

        for sender in possible_assignments[index]:
            if index > 0 and sender == assignment[index - 1]:
                continue

            assignment[index] = sender
            if backtrack(index + 1):
                return True
            assignment[index] = None
        return False

    if backtrack(0):
        for i in range(m):
            print(f"{assignment[i]}:{messages[i].split(':', 1)[1]}")
    else:
        print("Impossible")


t = int(input())
for _ in range(t):
    solve()

