import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    adj = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        adj[i][i] = 0

    for _ in range(m):
        u, v, c = map(int, sys.stdin.readline().split())
        u -= 1
        v -= 1
        edges.append((u, v, c))
        adj[u][v] = min(adj[u][v], c)
        adj[v][u] = min(adj[v][u], c)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                adj[i][j] = min(adj[i][j], adj[i][k] + adj[k][j])

    not_in_shortest_path_count = 0
    for u, v, c in edges:
        is_in_shortest_path = False
        for i in range(n):
            for j in range(n):
                if i != j:
                    if adj[i][j] == adj[i][u] + c + adj[v][j] or adj[i][j] == adj[i][v] + c + adj[u][j]:
                        is_in_shortest_path = True
                        break
            if is_in_shortest_path:
                break
        if not is_in_shortest_path:
            not_in_shortest_path_count += 1

    print(not_in_shortest_path_count)

if __name__ == "__main__":
    solve()
