import sys

sys.setrecursionlimit(200005)

def solve():
    n, k = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))
    adj = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    def dfs(u, p, order, visited_count):
        if visited_count[0] == k:
            return
        order.append(u)
        visited_count[0] += 1
        for v in adj[u]:
            if v != p:
                dfs(v, u, order, visited_count)
                if visited_count[0] == k:
                    return

    def check(threshold):
        for root in range(n):
            for _ in range(n):
                for i in range(n):
                    adj[i].sort(key=lambda x: a[x] >= threshold, reverse=True)

                order = []
                visited_count = [0]
                dfs(root, -1, order, visited_count)

                if visited_count[0] == k:
                    min_val = float('inf')
                    for node_idx in order:
                        min_val = min(min_val, a[node_idx])
                    if min_val >= threshold:
                        return True
        return False

    low = 1
    high = 1000001
    ans = 0
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1
    print(ans)

solve()
