def solve():
    n, s = input().split()
    n = int(n)
    count = 0

    complement_map = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}

    for i in range(n):
        for j in range(i, n):
            sub = s[i:j+1]
            sub_len = len(sub)

            if sub_len == 0:
                continue

            complement_sub_list = [complement_map[char] for char in sub]
            complement_sub = "".join(complement_sub_list)

            sub_counts = {}
            for char in sub:
