import sys

def solve():
    n = int(sys.stdin.readline())
    passwords = [sys.stdin.readline().strip() for _ in range(n)]

    adj = [[] for _ in range(26)]
    for password in passwords:
        chars = set()
        for char in password:
            chars.add(ord(char) - ord('a'))

        for c1 in chars:
            for c2 in chars:
                if c1 != c2:
                    adj[c1].append(c2)
                    adj[c2].append(c1)

    visited = [False] * 26
    components = 0

    def dfs(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs(v)

    for i in range(26):
        if not visited[i]:
            has_edge = False
            for neighbor in adj[i]:
                if neighbor is not None:
                    has_edge = True
                    break

            if has_edge:
                dfs(i)
                components += 1
            else:
                # Check if this character actually appears in any password
                char_appears = False
                for password in passwords:
                    if chr(ord('a') + i) in password:
                        char_appears = True
                        break
                if char_appears:
                    components += 1

    print(components)

solve()
