    for word in words:
        vowel_count = count_vowels(word)
        last_vowel = get_last_vowel(word)
        if last_vowel:
            word_info.append((word, vowel_count, last_vowel))

    vowel_groups = {}
    for word, vowel_count, last_vowel in word_info:
        if (vowel_count, last_vowel) not in vowel_groups:
            vowel_groups[(vowel_count, last_vowel)] = []
        vowel_groups[(vowel_count, last_vowel)].append(word)

    lyrics = []
    used_words = set()

