            for i in range(len(available_words)):
                word2 = available_words[i]
                if count_vowels(word1) == count_vowels(word2) and get_last_vowel(word1) == get_last_vowel(word2):
                    pairs.append((word1, word2))
                    available_words.pop(i)
                    found_match = True
                    break
            if not found_match:
                available_words.insert(0, word1) # Put it back if no match found


        for i in range(0, len(pairs) // 2 * 2, 2):
            if i + 1 < len(pairs):
                lyrics.append((pairs[i][0], pairs[i][1], pairs[i+1][0], pairs[i+1][1]))


    final_lyrics = []


    lyrics_by_first_word_vowel_count = {}
    for lyric in lyrics:
        first_word_vowel_count = count_vowels(lyric[0])
        if first_word_vowel_count not in lyrics_by_first_word_vowel_count:
            lyrics_by_first_word_vowel_count[first_word_vowel_count] = []
        lyrics_by_first_word_vowel_count[first_word_vowel_count].append(lyric)


    for vowel_count, lyric_list in lyrics_by_first_word_vowel_count.items():

        available_lyrics = list(lyric_list)

        while len(available_lyrics) >= 2:
            lyric1 = available_lyrics.pop(0)
            lyric2 = None
            for i in range(len(available_lyrics)):
                potential_lyric2 = available_lyrics[i]
                if count_vowels(lyric1[1]) == count_vowels(potential_lyric2[1]) and get_last_vowel(lyric1[1]) == get_last_vowel(potential_lyric2[1]) and get_last_vowel(lyric1[0]) == get_last_vowel(potential_lyric2[0]):
                    lyric2 = potential_lyric2
                    available_lyrics.pop(i)
                    break

            if lyric2:
                final_lyrics.append((lyric1[0], lyric1[1], lyric2[0], lyric2[1]))
            else:
                available_lyrics.insert(0, lyric1)

    print(len(final_lyrics))
    for lyric in final_lyrics:
        print(lyric[0], lyric[1])
        print(lyric[2], lyric[3])

solve()
