        rows = len(grid)
        cols = len(grid[0])

        if not any(grid[r][c] for r in range(rows) for c in range(cols)):
            return False

        visited_cells = set()

        def dfs(r, c, visited_path):
            if (r, c) in visited_path:
                return True

            visited_path.add((r, c))

            neighbors = []
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc]:
                    neighbors.append((nr, nc))

            if len(neighbors) > 2:
                return False

            for nr, nc in neighbors:
                if not dfs(nr, nc, visited_path):
                    return False
            return True

        # Find a starting chocolate
        start_r, start_c = -1, -1
        for r in range(rows):
            for c in range(cols):
                if grid[r][c]:
                    start_r, start_c = r, c
                    break
            if start_r != -1:
                break

        if start_r == -1:
            return False

