        # Check if it's a single connected component
        num_chocolates = sum(grid[r][c] for r in range(rows) for c in range(cols))
        if num_chocolates == 0:
            return False

        visited_dfs = set()

        def dfs_connectivity(r, c):
            if (r, c) in visited_dfs:
                return
            visited_dfs.add((r, c))
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
