        transposed_a = [[a[r][c] for r in range(n)] for c in range(m)]
        a = transposed_a
        n, m = m, n

    if n > 10:
        min_changes = float('inf')
        for row_mask in range(1 << m):
            current_changes = 0
            for r in range(n):
                row_val = 0
                for c in range(m):
                    if (row_mask >> c) & 1:
                        row_val |= (1 << c)

