def solve():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)

    dp = [-1] * (n + 1)
    visited = [0] * (n + 1)
    MOD = 10**9

    def count_routes(u):
        if u == 2:
            return 1
        if dp[u] != -1:
            return dp[u]
        if visited[u] == 1:
            return float('inf')
        if visited[u] == 2:
            return dp[u]

        visited[u] = 1
        total_routes = 0
        for v in adj[u]:
            res = count_routes(v)
            if res == float('inf'):
                dp[u] = float('inf')
                visited[u] = 2
                return float('inf')
            total_routes = (total_routes + res) % MOD

        dp[u] = total_routes
        visited[u] = 2
        return total_routes

    result = count_routes(1)

    if result == float('inf'):
        print("inf")
    else:
        print(result % MOD)

solve()
