import sys

def solve():
    n, nx, ny, nz = map(int, sys.stdin.readline().split())
    planetoids = []
    for i in range(n):
        m, x, y, z, vx, vy, vz = map(int, sys.stdin.readline().split())
        planetoids.append({
            'id': i,
            'mass': m,
            'pos': [x, y, z],
            'vel': [vx, vy, vz],
            'initial_pos': [x, y, z]
        })

    time = 0
    while True:
        locations = {}
        for p in planetoids:
            current_pos = tuple([(p['pos'][d] + p['vel'][d] * time) % dim for d, dim in enumerate([nx, ny, nz])])
            if current_pos not in locations:
                locations[current_pos] = []
            locations[current_pos].append(p)

        collided_this_step = False
        new_planetoids = []
        processed_ids = set()

        for loc, colliding_planets in locations.items():
            if len(colliding_planets) > 1:
                collided_this_step = True
                total_mass = 0
                sum_vx, sum_vy, sum_vz = 0, 0, 0
                for p in colliding_planets:
                    total_mass += p['mass']
                    sum_vx += p['vel'][0]
                    sum_vy += p['vel'][1]
                    sum_vz += p['vel'][2]
                    processed_ids.add(p['id'])

                avg_vx = sum_vx // len(colliding_planets)
                avg_vy = sum_vy // len(colliding_planets)
                avg_vz = sum_vz // len(colliding_planets)

                new_planetoids.append({
                    'id': -1, # Placeholder, will be re-assigned later
                    'mass': total_mass,
                    'pos': list(loc),
                    'vel': [avg_vx, avg_vy, avg_vz],
                    'initial_pos': list(loc) # Use collision location as initial for new planetoid
                })
            else:
                for p in colliding_planets:
                    if p['id'] not in processed_ids:
                        new_planetoids.append(p)
                        processed_ids.add(p['id'])

        if not collided_this_step:
            break

        planetoids = new_planetoids
        time += 1

    # If no collisions occurred, use initial positions
    if time == 0:
        for p in planetoids:
            p['pos'] = p['initial_pos']

    # Assign final planet IDs and sort
    planetoids.sort(key=lambda p: (-p['mass'], tuple(p['pos'])))
    for i, p in enumerate(planetoids):
        p['final_id'] = i

    print(len(planetoids))
    for p in planetoids:
        print(f"P{p['final_id']}: {p['mass']} {p['pos'][0]} {p['pos'][1]} {p['pos'][2]} {p['vel'][0]} {p['vel'][1]} {p['vel'][2]}")

solve()
