import sys

def solve():
    n, k = map(int, sys.stdin.readline().split())
    jewels = []
    for _ in range(n):
        s, v = map(int, sys.stdin.readline().split())
        jewels.append((s, v))

    max_jewel_size = 300
    jewels_by_size = [[] for _ in range(max_jewel_size + 1)]
    for s, v in jewels:
        jewels_by_size[s].append(v)

    for s in range(1, max_jewel_size + 1):
        jewels_by_size[s].sort(reverse=True)

    dp = [0] * (k + 1)

    for s in range(1, max_jewel_size + 1):
        if not jewels_by_size[s]:
            continue
        current_jewels = jewels_by_size[s]
        num_jewels = len(current_jewels)

        for current_k in range(k, s - 1, -1):
            for i in range(1, num_jewels + 1):
                if current_k - i * s >= 0:
                    value_to_add = sum(current_jewels[:i])
                    dp[current_k] = max(dp[current_k], dp[current_k - i * s] + value_to_add)
                else:
                    break

    results = []
    for current_k in range(1, k + 1):
        max_val = 0
        for size in range(1, current_k + 1):
            max_val = max(max_val, dp[size])
        results.append(max_val)

    print(*results)

solve()
