                animal_locations[animal] = []
            animal_locations[animal].append(i)

    misplaced_animals = False
    for i, (enclosure_type, animals) in enumerate(enclosures):
        for animal in animals:
            if animal != enclosure_type:
                misplaced_animals = True
                break
        if misplaced_animals:
            break

    if not misplaced_animals:
        print("FALSE ALARM")
        return

    # Build a graph where nodes are enclosures and edges represent direct travel
    # An edge exists between enclosure i and enclosure j if an animal in enclosure i
    # belongs to enclosure j, or an animal in enclosure j belongs to enclosure i.
    graph = {i: set() for i in range(n)}
    for i, (enclosure_type, animals) in enumerate(enclosures):
        for animal in animals:
            # Find the correct enclosure for this animal
            correct_enclosure_index = -1
            for j, (correct_type, _) in enumerate(enclosures):
                if animal == correct_type:
                    correct_enclosure_index = j
                    break
            if correct_enclosure_index != -1 and i != correct_enclosure_index:
                graph[i].add(correct_enclosure_index)
                graph[correct_enclosure_index].add(i)

    # Check if the graph is connected. If it is, then it's possible.
    # We can use BFS or DFS to check connectivity.
    visited = [False] * n
    queue = []

    # Find a starting node that has misplaced animals
    start_node = -1
    for i, (enclosure_type, animals) in enumerate(enclosures):
        for animal in animals:
            if animal != enclosure_type:
                start_node = i
                break
        if start_node != -1:
            break

    if start_node == -1: # Should not happen if misplaced_animals is True
        print("FALSE ALARM")
        return

    queue.append(start_node)
    visited[start_node] = True
    count_visited = 0

    while queue:
        u = queue.pop(0)
        count_visited += 1
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

    # If all enclosures that contain animals are visited, it's possible.
    # We need to consider only enclosures that have animals.
    enclosures_with_animals = set()
    for i, (_, animals) in enumerate(enclosures):
        if animals:
            enclosures_with_animals.add(i)

    if len(enclosures_with_animals) == 0: # No animals at all
        print("FALSE ALARM")
        return

    # Check if all enclosures that *should* be part of the movement are connected.
    # This means checking if all enclosures that have animals or are the target of animals are connected.
    relevant_enclosures = set()
    for i, (enclosure_type, animals) in enumerate(enclosures):
        if animals:
            relevant_enclosures.add(i)
        for animal in animals:
            for j, (correct_type, _) in enumerate(enclosures):
                if animal == correct_type:
                    relevant_enclosures.add(i)
                    relevant_enclosures.add(j)
                    break

    if not relevant_enclosures: # No animals to move
        print("FALSE ALARM")
        return

    # Re-run BFS/DFS starting from a relevant enclosure
    visited = {node: False for node in relevant_enclosures}
    queue = []

    # Pick an arbitrary starting node from relevant_enclosures
    start_node = next(iter(relevant_enclosures))
    queue.append(start_node)
    visited[start_node] = True
    visited_count = 0

    while queue:
        u = queue.pop(0)
        visited_count += 1
        for v in graph[u]:
            if v in relevant_enclosures and not visited[v]:
                visited[v] = True
                queue.append(v)

    if visited_count == len(relevant_enclosures):
        print("POSSIBLE")
    else:
        print("IMPOSSIBLE")

solve()
