def solve():
    n, d = map(int, sys.stdin.readline().split())
    frogs = []
    for _ in range(n):
        l, w, h = map(int, sys.stdin.readline().split())
        frogs.append((l, w, h))

    frogs.sort(key=lambda x: x[2])

    dp = [0] * (d + 1)
    total_weight_sum = sum(w for l, w, h in frogs)

    for l, w, h in frogs:
        for current_d in range(d, -1, -1):
            if current_d + l > d:
                dp[current_d] = max(dp[current_d], dp[current_d] + 1)

            if current_d - h >= 0:
                dp[current_d] = max(dp[current_d], dp[current_d - h])

    max_escaped = 0
    for current_d in range(d + 1):
        max_escaped = max(max_escaped, dp[current_d])

    print(max_escaped)

