MAX_K = 5000
primes = []
spf = [i for i in range(MAX_K + 1)]

for i in range(2, MAX_K + 1):
    if spf[i] == i:
        primes.append(i)
        for j in range(i * i, MAX_K + 1, i):
            if spf[j] == j:
                spf[j] = i

prime_counts = [0] * len(primes)
prime_to_idx = {p: i for i, p in enumerate(primes)}

n = int(input())
k_values = list(map(int, input().split()))

