        continue
    temp_k = k
    while temp_k > 1:
        p = spf[temp_k]
        count = 0
        while temp_k % p == 0:
            count += 1
            temp_k //= p
        prime_counts[prime_to_idx[p]] += count

total_path_length = 0
for i, p in enumerate(primes):
    count = prime_counts[i]
    if count > 0:
        total_path_length += count * (p - 1)

print(total_path_length)
