import sys

def get_prime_factors(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def solve():
    n = int(sys.stdin.readline())
    pairs = []
    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())
        pairs.append((a, b))

    possible_wcds = set()
    if n > 0:
        possible_wcds.update(get_prime_factors(pairs[0][0]))
        possible_wcds.update(get_prime_factors(pairs[0][1]))

    for wcd_candidate in possible_wcds:
        is_valid = True
        for i in range(1, n):
            a, b = pairs[i]
            if a % wcd_candidate != 0 and b % wcd_candidate != 0:
                is_valid = False
                break
        if is_valid:
            print(wcd_candidate)
            return

    print(-1)

if __name__ == "__main__":
    solve()
