import sys

def solve():
    n, c = map(int, sys.stdin.readline().split())
    encounters = {}
    for _ in range(c):
        a, b, y = map(int, sys.stdin.readline().split())
        encounters[(a, b)] = y
        encounters[(b, a)] = y

    all_years = set()
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i, j) in encounters:
                all_years.add(encounters[(i, j)])
            else:
                all_years.add(2008)
    all_years = sorted(list(all_years))

    for y in all_years:
        group1 = set()
        group2 = set()

        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                met_year = encounters.get((i, j), 2008)
                if met_year < y:
                    group1.add(i)
                    group1.add(j)
                elif met_year >= y:
                    group2.add(i)
                    group2.add(j)

        # Check if all participants are assigned
        all_participants = set(range(1, n + 1))
        assigned_participants = group1.union(group2)
        if all_participants != assigned_participants:
            continue

        # Check size constraints
        if len(group1) <= (2 * n) // 3 and len(group2) <= (2 * n) // 3:
            print(y)
            return

    print("Impossible")

if __name__ == "__main__":
