def solve():
    n = int(input())
    colors = []
    for _ in range(n):
        colors.append(list(map(int, input().split())))

    MOD = 10**9 + 7

    total_sum = 0

    for i in range(1, 1 << n):
        subset_nodes = []
        for j in range(n):
            if (i >> j) & 1:
                subset_nodes.append(j)

        if not subset_nodes:
            continue

        max_f_S = 0

        for color_val in range(1, 301):
            nodes_with_color = []
            for node_idx in subset_nodes:
                is_connected_with_color = False
                for other_node_idx in subset_nodes:
                    if node_idx != other_node_idx and colors[node_idx][other_node_idx] == color_val:
                        is_connected_with_color = True
                        break
                if is_connected_with_color:
                    nodes_with_color.append(node_idx)

            if not nodes_with_color:
                continue

            # Now, for this specific color, find the maximum clique in the subgraph
            # formed by nodes_with_color where all edges have color_val.
            # This is equivalent to finding the size of the largest connected component
            # in the subgraph where all edges have color_val.

            # Build adjacency list for the subgraph with the current color
            adj_list = {node: [] for node in nodes_with_color}
            for u_idx in range(len(nodes_with_color)):
                for v_idx in range(u_idx + 1, len(nodes_with_color)):
                    u = nodes_with_color[u_idx]
                    v = nodes_with_color[v_idx]
                    if colors[u][v] == color_val:
                        adj_list[u].append(v)
                        adj_list[v].append(u)

            visited = set()
            current_max_component_size = 0

            for start_node in nodes_with_color:
                if start_node not in visited:
                    component_size = 0
                    stack = [start_node]
                    visited.add(start_node)
                    while stack:
                        node = stack.pop()
                        component_size += 1
                        for neighbor in adj_list[node]:
                            if neighbor not in visited:
                                visited.add(neighbor)
                                stack.append(neighbor)
                    current_max_component_size = max(current_max_component_size, component_size)

            max_f_S = max(max_f_S, current_max_component_size)

        total_sum = (total_sum + max_f_S) % MOD

    print(total_sum)

solve()
