def solve():
    n = int(sys.stdin.readline())
    heights = []
    for _ in range(n):
        heights.append(list(map(int, sys.stdin.readline().split())))

    speeds = []
    for _ in range(n):
        speeds.append(list(map(int, sys.stdin.readline().split())))

    max_group_size = 0

    # We need to consider all possible times.
    # The critical times are when two trees become the same height.
    # h1 + v1*t = h2 + v2*t
    # t * (v1 - v2) = h2 - h1
    # t = (h2 - h1) / (v1 - v2)
    # We only care about positive times.

    critical_times = set()
    critical_times.add(0) # Initial state

    for r1 in range(n):
        for c1 in range(n):
            for r2 in range(n):
                for c2 in range(n):
                    if r1 == r2 and c1 == c2:
                        continue

                    h1 = heights[r1][c1]
                    v1 = speeds[r1][c1]
                    h2 = heights[r2][c2]
                    v2 = speeds[r2][c2]

                    if v1 != v2:
                        numerator = h2 - h1
                        denominator = v1 - v2
                        if denominator > 0 and numerator >= 0:
                            critical_times.add(numerator / denominator)
                        elif denominator < 0 and numerator <= 0:
                            critical_times.add(numerator / denominator)

    sorted_critical_times = sorted(list(critical_times))

    for t in sorted_critical_times:
        current_heights = [[heights[r][c] + speeds[r][c] * t for c in range(n)] for r in range(n)]

        visited = [[False for _ in range(n)] for _ in range(n)]

        for r in range(n):
            for c in range(n):
                if not visited[r][c]:
                    current_height = current_heights[r][c]
                    group_size = 0

                    stack = [(r, c)]
                    visited[r][c] = True

                    while stack:
                        row, col = stack.pop()
                        group_size += 1

                        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
