def solve():
    n = int(input())
    s = input()

    counts = Counter(s)
    odd_counts = 0
    for count in counts.values():
        if count % 2 != 0:
            odd_counts += 1

    if odd_counts == 0:
        print(1)
        print("".join(sorted(s)))
        return

    for k in range(odd_counts, n + 1):
        if n % k == 0:
            length = n // k
            if length >= 2 * odd_counts - 2:
                print(k)
                parts = []
                remaining_counts = counts.copy()

                odd_chars = []
                for char, count in remaining_counts.items():
                    if count % 2 != 0:
                        odd_chars.append(char)
                        remaining_counts[char] -= 1

                for _ in range(k):
                    current_part_chars = []

                    # Add pairs
                    for char, count in remaining_counts.items():
                        current_part_chars.extend([char] * (count // k))
                        remaining_counts[char] -= (count // k) * k

                    # Distribute odd characters
                    if odd_chars:
                        current_part_chars.append(odd_chars.pop(0))

                    current_part_chars.sort()

                    # Construct palindrome
                    half_len = len(current_part_chars) // 2
                    palindrome = "".join(current_part_chars[:half_len]) + "".join(current_part_chars[half_len:])

                    # Pad with remaining odd characters if needed
                    while len(palindrome) < length:
                        if odd_chars:
                            palindrome = palindrome[:len(palindrome)//2] + odd_chars.pop(0) + palindrome[len(palindrome)//2:]
                        else:
                            # This case should ideally not happen if length >= 2 * odd_counts - 2
                            # but as a fallback, we can add any character if available
                            for char, count in remaining_counts.items():
                                if count > 0:
                                    palindrome = palindrome[:len(palindrome)//2] + char + palindrome[len(palindrome)//2:]
                                    remaining_counts[char] -= 1
                                    break

                    parts.append(palindrome)

                print(*parts)
                return

