import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    if m == n * (n - 1) // 2:
        print(0)
        print()
        return

    min_steps = float('inf')
    best_selection = []

    for i in range(1 << n):
        selected_nodes = []
        for j in range(n):
            if (i >> j) & 1:
                selected_nodes.append(j + 1)

        if not selected_nodes:
            continue

        current_adj = [set(neighbors) for neighbors in adj]

        for node in selected_nodes:
            friends_of_node = list(current_adj[node])
            for k in range(len(friends_of_node)):
                for l in range(k + 1, len(friends_of_node)):
                    f1 = friends_of_node[k]
                    f2 = friends_of_node[l]
                    current_adj[f1].add(f2)
                    current_adj[f2].add(f1)

        is_complete = True
        for u in range(1, n + 1):
            if len(current_adj[u]) != n - 1:
                is_complete = False
                break

        if is_complete:
            if len(selected_nodes) < min_steps:
                min_steps = len(selected_nodes)
                best_selection = selected_nodes

    print(min_steps)
    print(*best_selection)

solve()
