import sys

def solve():
    w, p = map(int, sys.stdin.readline().split())
    wells = []
    for _ in range(w):
        wells.append(list(map(int, sys.stdin.readline().split())))

    pipes = []
    for _ in range(p):
        s, x, y = map(int, sys.stdin.readline().split())
        pipes.append((s - 1, (x, y)))

    def intersect(p1_start, p1_end, p2_start, p2_end):
        x1, y1 = p1_start
        x2, y2 = p1_end
        x3, y3 = p2_start
        x4, y4 = p2_end

        den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
        if den == 0:
            return False

        t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den
        u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / den

        if 0 < t < 1 and 0 < u < 1:
            return True
        return False

    adj = [[] for _ in range(p)]
    for i in range(p):
        for j in range(i + 1, p):
            well_i_idx = pipes[i][0]
            well_j_idx = pipes[j][0]
            pipe_i_start = wells[well_i_idx]
            pipe_i_end = pipes[i][1]
            pipe_j_start = wells[well_j_idx]
            pipe_j_end = pipes[j][1]

            if intersect(pipe_i_start, pipe_i_end, pipe_j_start, pipe_j_end):
                adj[i].append(j)
                adj[j].append(i)

    # Check for bipartite graph using BFS
    color = [-1] * p
    is_bipartite = True

    for start_node in range(p):
        if color[start_node] == -1:
            queue = [start_node]
            color[start_node] = 0
            while queue:
                u = queue.pop(0)
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        is_bipartite = False
                        break
                if not is_bipartite:
                    break
        if not is_bipartite:
            break

    if is_bipartite:
        print("possible")
    else:
        print("impossible")

solve()
