import sys

def solve():
    n = int(sys.stdin.readline())
    friends = []
    for _ in range(n):
        w, h = map(int, sys.stdin.readline().split())
        friends.append((w, h))

    min_area = float('inf')

    for max_h in range(1, 1001):
        possible_height = True
        for w, h in friends:
            if w > max_h and h > max_h:
                possible_height = False
                break
        if not possible_height:
            continue

        dp = [[float('inf')] * (n // 2 + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(n):
            w, h = friends[i]
            for j in range(i + 1):
                for k in range(n // 2 + 1):
                    if dp[j][k] == float('inf'):
                        continue

                    # Stand
                    if h <= max_h:
                        dp[j + 1][k] = min(dp[j + 1][k], dp[j][k] + w)

                    # Lie down
                    if w <= max_h and k + 1 <= n // 2:
                        dp[j + 1][k + 1] = min(dp[j + 1][k + 1], dp[j][k] + h)

        for k in range(n // 2 + 1):
            if dp[n][k] != float('inf'):
                min_area = min(min_area, dp[n][k] * max_h)

    print(min_area)

solve()
