def solve_puzzle():
    grid = [input() for _ in range(4)]

    def get_row_cost(row_idx, target_row):
        current_row = grid[row_idx]
        min_moves = float('inf')
        for shift in range(4):
            shifted_row = current_row[shift:] + current_row[:shift]
            if shifted_row == target_row:
                min_moves = min(min_moves, shift)

            shifted_row_rev = current_row[::-1]
            shifted_row_rev = shifted_row_rev[shift:] + shifted_row_rev[:shift]
            if shifted_row_rev == target_row:
                min_moves = min(min_moves, shift + 1) # +1 for reversing
        return min_moves

    def get_col_cost(col_idx, target_col):
        current_col = "".join(grid[i][col_idx] for i in range(4))
        min_moves = float('inf')
        for shift in range(4):
            shifted_col = current_col[shift:] + current_col[:shift]
            if shifted_col == target_col:
                min_moves = min(min_moves, shift)

            shifted_col_rev = current_col[::-1]
            shifted_col_rev = shifted_col_rev[shift:] + shifted_col_rev[:shift]
            if shifted_col_rev == target_col:
                min_moves = min(min_moves, shift + 1) # +1 for reversing
        return min_moves

    target_rows = ["RRRR", "GGGG", "BBBB", "YYYY"]
    target_cols = ["R", "G", "B", "Y"]

    min_total_moves = float('inf')

    import itertools
    for row_perm in itertools.permutations(range(4)):
        row_moves = 0
        for i in range(4):
            row_moves += get_row_cost(i, target_rows[row_perm[i]])

        for col_perm in itertools.permutations(range(4)):
            col_moves = 0
            for j in range(4):
                col_moves += get_col_cost(j, target_cols[col_perm[j]])
            min_total_moves = min(min_total_moves, row_moves + col_moves)

    print(min_total_moves)

